  "<span>First assign a Design Field to at least one object in the design (right panel), then AI will fill them.</span></div></div>": "<span>Najpierw przypisz pole projektu do co najmniej jednego obiektu w projekcie (prawy panel), a następnie AI je wypełni.</span></div></div>",
  "This request comes from the Bulk Builder (PLAN pass). Read the instruction and the design fields, then LIST the outputs you will produce, LABELS ONLY (no field content). Return ONLY a raw JSON object: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. When translate is true the labels are the LANGUAGE NAMES (written in the same language the user used). Otherwise the labels are a distinct short topic/seed per output. Honor any quantity named in the instruction; otherwise a sensible set (about 6 to 12). Hard cap 500.\n": "To żądanie pochodzi z narzędzia Bulk Builder (karta PLAN). Przeczytaj instrukcję i pola projektu, a następnie WYPISZ wyniki, które wygenerujesz, TYLKO ETYKIETY (bez zawartości pola). Zwróć TYLKO surowy obiekt JSON: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. Jeśli tłumaczenie ma wartość true, etykietami są NAZWY JĘZYKÓW (zapisane w tym samym języku, którego używał użytkownik). W przeciwnym razie etykiety stanowią odrębny krótki temat/zalążek dla każdego produktu. Honoruj ​​każdą ilość wymienioną w instrukcji; w przeciwnym razie rozsądny zestaw (około 6 do 12). Twardy limit 500.\n",
