  "<button id=\"set-clear-cache\" class=\"sbtn\" style=\"padding:8px 16px;width:auto;height:auto;font-size:12px;border-color:var(--red);color:var(--red)\">Clear All Cache</button>": "<button id=\"set-clear-cache\" class=\"sbtn\" style=\"padding:8px 16px;width:auto;height:auto;font-size:12px;border-color:var(--red);color:var(--red)\">Wyczyść całą pamięć podręczną</button>",
  "settings: preferences": "ustawienia: preferencje",
