  "settings: sleep": "ustawienia: sen",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Auto-save times from this browser. The latest state is stored under <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; rolling snapshots use <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Automatycznie zapisuj czasy z tej przeglądarki. Ostatni stan jest przechowywany w <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; kroczące migawki używają <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>",
  "<div style=\"font-size:14px;color:var(--text)\">": "<div style=\"font-size:14px;color:var(--text)\">",
  "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">No <code>dika_autosave</code> entry yet.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">Nie ma jeszcze wpisu <code>dika_autosave</code>.</p>",
  "<ul id=\"settings-vh-list\" style=\"margin:0 0 12px 0;padding:0 0 0 18px;color:var(--text-dim);font-size:12px;max-height:240px;overflow-y:auto;line-height:1.4\">": "<ul id=\"settings-vh-list\" style=\"margin:0 0 12px 0;padding:0 0 0 18px;color:var(--text-dim);font-size:12px;max-height:240px;overflow-y:auto;line-height:1.4\">",
