  "<p style=\"color:var(--text-faint);font-size:12px;margin-bottom:12px\">No rolling snapshots yet (they are added on each auto-save tick).</p>": "<p style=\"color:var(--text-faint);font-size:12px;margin-bottom:12px\">Brak migawek kroczących (są dodawane przy każdym automatycznym zapisie).</p>",
  "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Clears stored version snapshots (<code>dika_versions</code>). Current canvas and latest auto-save file are not removed.</span>": "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Czyści zapisane migawki wersji (<code>dika_versions</code>). Bieżący obszar roboczy i najnowszy plik automatycznego zapisu nie są usuwane.</span>",
