  "A new page will open as your whiteboard. You can draw, add shapes, sticky notes and connectors freely across the entire canvas.": "Nowa strona otworzy się jako biała tablica. Możesz swobodnie rysować oraz dodawać kształty, karteczki i łączniki na całym obszarze.",
