  "Add products from the panel's Assets > Products section, and they'll appear here automatically.": "Dodaj produkty z panelu Zasoby > Produkty, a pojawią się one tutaj automatycznie.",
  "A design and video studio that runs on this machine.": "Studio projektowe i wideo działające na tym komputerze.",
  "Your work stays here. Documents, media and version history never leave this computer.": "Twoja praca zostaje tutaj. Dokumenty, multimedia i historia wersji nigdy nie opuszczają tego komputera.",
  "Free to use. Source available under the Business Source License 1.1.": "Bezpłatne w użyciu. Kod źródłowy dostępny na Business Source License 1.1.",
  "Your projects are stored in this browser profile. That is the only copy.": "Twoje projekty są przechowywane w tym profilu przeglądarki. To jedyny egzemplarz.",
  "Clearing site data deletes them. So does a different browser, or a fresh profile.": "Wyczyszczenie danych witryn powoduje ich usunięcie. Podobnie jest w przypadku innej przeglądarki lub nowego profilu.",
  "Export a project file for anything you want to keep. It carries the design and its media, and it opens on any machine.": "Wyeksportuj plik projektu zawierający wszystko, co chcesz zachować. Zawiera projekt i jego multimedia i otwiera się na dowolnym komputerze.",
  "Export a project file now": "Wyeksportuj teraz plik projektu",
  "Remind me to export": "Przypomnij mi o wyeksportowaniu",
  "Never": "Nigdy",
  "Weekly": "Tygodnik",
  "Monthly": "Miesięczny",
  "That is everything. Your work stays on this machine.": "To wszystko. Twoja praca pozostaje na tym komputerze.",
  "You can reopen this from Settings > About.": "Możesz je ponownie otworzyć, wybierając Ustawienia > Informacje.",
  "Start using it": "Zacznij go używać",
  "Your profile data is used in contact presets and bulk export.": "Dane profilu są używane w ustawieniach kontaktów i eksporcie zbiorczym.",
  "JOB TITLE": "TYTUŁ PRACY",
  "ADDRESS": "ADRES",
  "Social Media": "Media społecznościowe",
  "Save Profile": "Zapisz profil",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way, online or offline.": "Konto zapewnia dostęp do szablonów online, biblioteki zasobów i informacji o wydaniach. Edytor działa online i offline.",
  "Sign in to unlock:": "Zaloguj się, aby odblokować:",
  "The online template and asset library": "Internetowa biblioteka szablonów i zasobów",
  "Release news and early access to new features": "Publikuj nowości i wcześniejszy dostęp do nowych funkcji",
  "The editor itself works either way, with or without an account, online or offline.": "Sam edytor działa w obie strony, z kontem lub bez, online lub offline.",
  "Create an account": "Utwórz konto",
  "WHAT THIS APP SENDS": "CO WYSYŁA TA APLIKACJA",
  "Once a day: an install id, the app version, your platform and language, and your account id once you sign in.": "Raz dziennie: identyfikator instalacji, wersja aplikacji, platforma i język oraz identyfikator konta po zalogowaniu.",
  "Nothing about your designs. No document, no title, no file name, no image.": "Brak informacji o projektach: dokumentu, tytułu, nazwy pliku ani obrazu.",
  "WHERE THE SESSION IS KEPT": "GDZIE ODBYWA SIĘ SESJA",
  "You are running the browser build, where every local page shares one storage area, so another local file opened in this browser could read this session. It is therefore short-lived (about 24 hours) and can only read the template library. The desktop app keeps its own isolated storage.": "Używasz wersji przeglądarki, w której każda strona lokalna ma wspólny obszar przechowywania, więc inny plik lokalny otwarty w tej przeglądarce może odczytać tę sesję. Jest zatem krótkotrwały (około 24 godzin) i może jedynie czytać bibliotekę szablonów. Aplikacja komputerowa utrzymuje własną, izolowaną pamięć.",
  "Your own keys for the stock media providers. They fill the Images and Audio search tabs, and the GIFs and Stickers tabs in Items. Every provider below has a free tier.": "Twoje klucze dostępu do dostawców mediów stockowych. Służą do wyszukiwania obrazów i dźwięku oraz GIF-ów i naklejek w sekcji Elementy. Każdy dostawca poniżej oferuje darmowy pakiet.",
  "These keys are stored in this browser only, and this build never sends them anywhere except to the provider itself. Anyone with access to this computer or its browser profile can read them, so use a restricted key with the lowest quota you need.": "Klucze te są przechowywane tylko w tej przeglądarce, a ta kompilacja nigdy nie wysyła ich nigdzie poza samym dostawcą. Każdy, kto ma dostęp do tego komputera lub jego profilu przeglądarki, może je odczytać, więc użyj zastrzeżonego klucza z najniższym potrzebnym przydziałem.",
  "Save keys": "Zapisz klucze",
  "1. Go to unsplash.com/oauth/applications and create an app": "1. Przejdź do unsplash.com/oauth/applications i utwórz aplikację",
  "2. Copy the Access Key, not the Secret Key": "2. Skopiuj klucz dostępu, a nie tajny klucz",
  "Header: Authorization: Client-ID YOUR_KEY - 50 req/hr on demo, 5000 req/hr in production": "Nagłówek: Autoryzacja: Client-ID YOUR_KEY - 50 zapotrzebowań/godz. w wersji demonstracyjnej, 5000 zapotrzebowań/godz. w produkcji",
  "1. Go to pexels.com/api and request a key": "1. Wejdź na pexels.com/api i poproś o klucz",
  "2. It is issued instantly": "2. Wydawany jest natychmiastowo",
  "Header: Authorization: YOUR_KEY - 200 req/hr, 20K req/month": "Nagłówek: Autoryzacja: YOUR_KEY - 200 zapotrzebowań/godz., 20 tys. zapotrzebowań/miesiąc",
  "1. Go to pixabay.com/api/docs/ and sign up": "1. Wejdź na pixabay.com/api/docs/ i zarejestruj się",
  "2. Copy the key shown on the docs page": "2. Skopiuj klucz pokazany na stronie dokumentów",
  "500K+ CC-licensed sound effects - header: Authorization: Token YOUR_KEY": "Ponad 500 000 efektów dźwiękowych na licencji CC - nagłówek: Autoryzacja: Token YOUR_KEY",
  "1. Go to freesound.org/apiv2/apply and create an API app": "1. Przejdź do freesound.org/apiv2/apply i utwórz aplikację API",
  "2. Copy the API Token": "2. Skopiuj token API",
  "1. Go to devportal.jamendo.com and register an app": "1. Przejdź do devportal.jamendo.com i zarejestruj aplikację",
  "2. Copy the Client ID": "2. Skopiuj identyfikator klienta",
  "1. Go to developers.giphy.com and create an app": "1. Przejdź do strony Developers.giphy.com i utwórz aplikację",
  "2. Copy the API Key": "2. Skopiuj klucz API",
