  "No data yet.": "Brak danych.",
  "Auto-save times from this browser. The latest state is stored under dika_autosave; rolling snapshots use dika_versions.": "Automatycznie zapisuj czasy z tej przeglądarki. Najnowszy stan jest przechowywany w dika_autosave; kroczące migawki używają dika_versions.",
  "Clear History": "Wyczyść historię",
  "Customize shortcuts, manage profiles, and resolve conflicts across all app modules.": "Dostosuj skróty, zarządzaj profilami i rozwiązuj konflikty we wszystkich modułach aplikacji.",
  "All Categories": "Wszystkie kategorie",
