  "Sound Effects": "Efekty dźwiękowe",
  "Skip Startup Wizard": "Pomiń kreatora uruchamiania",
  "In multi-page projects, to keep the app fast, pages you haven't opened for a long time are put to sleep in the background. Their content is safely stored and instantly returns when you click its tab. The page you're working on, a few nearby pages, and video / infinite canvas / slide / board pages always stay open.": "W projektach wielostronicowych strony, których dawno nie otwierano, są usypiane w tle, aby aplikacja działała szybko. Ich zawartość jest bezpiecznie przechowywana i natychmiast wraca po kliknięciu karty. Aktualna strona, kilka sąsiednich stron oraz strony wideo, nieskończonej kanwy, slajdów i tablicy pozostają zawsze otwarte.",
  "Automatic sleep": "Automatyczne usypianie",
  "Maximum awake pages (pages older than this number sleep)": "Maksymalna liczba aktywnych stron (starsze strony przechodzą w stan uśpienia)",
  "Neighbor window (pages kept awake on each side of the active page)": "Okno sąsiedztwa (strony utrzymywane aktywne po obu stronach bieżącej strony)",
  "AWAKE": "OBUDZONY",
  "ASLEEP": "WE ŚNIE",
  "TOTAL": "CAŁKOWITY",
  "Sleep all": "Śpijcie wszyscy",
  "Upload Settings": "Ustawienia przesyłania",
  "Configure image upload queue behavior for gallery imports.": "Skonfiguruj zachowanie kolejki przesyłania obrazów dla importu galerii.",
  "Queue Settings": "Ustawienia kolejki",
  "Concurrent Uploads": "Równoczesne przesyłanie",
  "1 (Sequential)": "1 (sekwencyjny)",
  "3 (Default)": "3 (domyślnie)",
  "Number of images processed at once. Use 1 for weak servers, Unlimited for local.": "Liczba obrazów przetwarzanych jednocześnie. Użyj 1 dla słabych serwerów i „Bez limitu” lokalnie.",
